package dev.aserver.motionrp.core;
import com.google.gson.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class BrolyAssetsTest {
 private JsonObject load(String file)throws Exception{try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/bettermodel/"+file+".bbmodel"))){return JsonParser.parseString(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}}
 @Test void boundedFlightCapsAt24BlocksAndKeepsABufferBeforeTheHit(){
  double d=0;for(int i=0;i<100;i++){double next=BrolyTimeline.nextDistance(d);assertTrue(next>=d&&next-d<=1.5);d=next;}assertEquals(24,d);assertEquals(0,BrolyTimeline.safeTravel(1.5,.02));assertEquals(.42,BrolyTimeline.safeTravel(1.5,.5),1e-9);assertEquals(1.5,BrolyTimeline.safeTravel(1.5,8));
 }
 @Test void earlyAndDistantImpactsHaveTheirOwnPhaseClock(){
  assertEquals("FLEE",BrolyTimeline.phase(20,-1));assertEquals("TURN",BrolyTimeline.phase(28,-1));assertEquals("CHARGE",BrolyTimeline.phase(40,-1));assertEquals("GRAB",BrolyTimeline.phase(50,-1));assertEquals("FLIGHT",BrolyTimeline.phase(56,-1));for(int impact:new int[]{56,60,71}){assertEquals("IMPACT",BrolyTimeline.phase(impact,impact));assertEquals("RECOVER",BrolyTimeline.phase(impact+20,impact));assertTrue(impact+20<BrolyTimeline.END);}
 }
 @Test void allPhaseAnimationsPreserveTheIndependentClockBone()throws Exception{
  for(String role:List.of("attacker","victim")){var m=load("players/motionrp_broly_"+role);String root=m.getAsJsonArray("groups").asList().stream().map(JsonElement::getAsJsonObject).filter(g->g.get("name").getAsString().equals("player_root")).findFirst().orElseThrow().get("uuid").getAsString();Set<String> clips=new HashSet<>();for(var raw:m.getAsJsonArray("animations")){var a=raw.getAsJsonObject();String name=a.get("name").getAsString();clips.add(name);assertTrue(a.get("override").getAsBoolean());if(name.startsWith("broly_")){assertEquals(7.2,a.get("length").getAsDouble());assertTrue(a.getAsJsonObject("animators").has(root));}else assertFalse(a.getAsJsonObject("animators").has(root),"Phase changes must not replace the shared recovery clock");}assertTrue(clips.containsAll(Set.of("flee","turn","charge","fright","grapple","flight","impact","recover")));}
 }
 @Test void brolyInvitationsRequireTheirOwnAcceptance(){var sessions=new PairSessions();var a=UUID.randomUUID();var b=UUID.randomUUID();assertTrue(sessions.invite(a,b,0,"broly"));assertTrue(sessions.accept(b,a,1,"fusion").isEmpty());assertTrue(sessions.accept(b,a,1,"finalbattle").isEmpty());assertEquals("broly",sessions.accept(b,a,2,"broly").orElseThrow().kind());}
 @Test void cosmeticWallAndCracksHaveRealGeometry()throws Exception{for(String id:List.of("wall","crater")){var m=load("models/motionrp_broly_"+id);assertFalse(m.getAsJsonArray("elements").isEmpty());assertFalse(m.getAsJsonArray("outliner").isEmpty());}}
 @Test void chaseWaitsForTheVictimToTurnAndThenClosesTheGap(){
  assertEquals(0,BrolyTimeline.fleeDistance(0));assertEquals(4,BrolyTimeline.fleeDistance(BrolyTimeline.TURN));assertEquals(4,BrolyTimeline.fleeDistance(100));assertEquals(0,BrolyTimeline.turnProgress(BrolyTimeline.TURN));assertEquals(1,BrolyTimeline.turnProgress(BrolyTimeline.CHARGE));assertEquals(0,BrolyTimeline.chargeProgress(BrolyTimeline.CHARGE));assertEquals(1,BrolyTimeline.chargeProgress(BrolyTimeline.GRAB));assertTrue(BrolyTimeline.TURN<BrolyTimeline.CHARGE&&BrolyTimeline.CHARGE<BrolyTimeline.GRAB&&BrolyTimeline.GRAB<BrolyTimeline.LAUNCH);
 }
 @Test void old032RolesUpgradeWithBackupsAndCustomRolesRemain()throws Exception{
  var root=java.nio.file.Files.createTempDirectory("broly-033");for(String role:List.of("attacker","victim")){String file="players/motionrp_broly_"+role+".bbmodel";byte[] old;try(var in=new java.util.zip.GZIPInputStream(getClass().getResourceAsStream("/bundled-0.32.0/"+file.replace('/','_')+".gz"))){old=in.readAllBytes();}byte[] now;try(var in=getClass().getResourceAsStream("/bettermodel/"+file)){now=in.readAllBytes();}var target=root.resolve(file);java.nio.file.Files.createDirectories(target.getParent());java.nio.file.Files.write(target,old);var u=new BundledAssetUpdater();var hashes=BundledAssetVersions.knownHashes(file,Set.of());assertEquals(BundledAssetUpdater.Result.UPDATED,u.install(target,now,hashes,root.resolve("backups"),root.resolve("updates")));assertTrue(java.nio.file.Files.exists(root.resolve("backups").resolve(target.getFileName()+"."+BundledAssetUpdater.sha256(old)+".bak")));java.nio.file.Files.writeString(target,"custom");assertEquals(BundledAssetUpdater.Result.CUSTOM_PRESERVED,u.install(target,now,hashes,root.resolve("backups"),root.resolve("updates")));}
 }

 @Test void bothRolesRiseSmoothlyAndTheDentHasABoundedDepth(){
  double last=0;for(int t=0;t<40;t++){double h=BrolyTimeline.lift(t);assertTrue(h>=last&&h<=1.15);last=h;}assertEquals(1.15,last);assertEquals(0,BrolyTimeline.dentProgress(0));assertEquals(1,BrolyTimeline.dentProgress(8));assertEquals(2.4,BrolyTimeline.DENT_DEPTH);
 }
 @Test void largeGreyWallHasARealCircularBowlAndASeparateUnbrokenFace()throws Exception{
  var flat=load("models/motionrp_broly_wall");var dent=load("models/motionrp_broly_dented_wall");var e=dent.getAsJsonArray("elements").get(0).getAsJsonObject();var v=e.getAsJsonObject("vertices");assertEquals(-12,v.getAsJsonArray("0_0").get(2).getAsDouble(),1e-6);
  double minX=1000,maxX=-1000;for(int k=0;k<64;k++){var p=v.getAsJsonArray("8_"+k);assertEquals(20,Math.hypot(p.get(0).getAsDouble(),p.get(1).getAsDouble()),1e-6);}for(var p:v.entrySet()){double x=p.getValue().getAsJsonArray().get(0).getAsDouble();minX=Math.min(minX,x);maxX=Math.max(maxX,x);}assertEquals(72,maxX-minX,1e-6);
  var fv=flat.getAsJsonArray("elements").get(0).getAsJsonObject().getAsJsonObject("vertices");for(var p:fv.entrySet())if(!p.getKey().startsWith("back"))assertTrue(Math.abs(p.getValue().getAsJsonArray().get(2).getAsDouble())<.2,"Unbroken face is not already cratered");
  var clips=new HashSet<String>();for(var raw:dent.getAsJsonArray("animations"))clips.add(raw.getAsJsonObject().get("name").getAsString());assertTrue(clips.containsAll(Set.of("flat","dent")));
 }
 @Test void flyingEscapeKeepsItsLegsInAFlyingPoseRatherThanAlternatingSteps()throws Exception{
  for(String role:List.of("attacker","victim")){var m=load("players/motionrp_broly_"+role);var a=m.getAsJsonArray("animations").asList().stream().map(JsonElement::getAsJsonObject).filter(x->x.get("name").getAsString().equals("flee")).findFirst().orElseThrow();for(var track:a.getAsJsonObject("animators").entrySet()){var t=track.getValue().getAsJsonObject();String name=t.get("name").getAsString();if(name.equals("prl_right_leg")||name.equals("pll_left_leg"))for(var key:t.getAsJsonArray("keyframes")){var p=key.getAsJsonObject().getAsJsonArray("data_points").get(0).getAsJsonObject();assertTrue(p.get("x").getAsDouble()<0,"Flight legs trail behind throughout the clip");}}}
 }
 @Test void old033RolesAndRockModelsUpgradeWithBackups()throws Exception{
  var root=java.nio.file.Files.createTempDirectory("broly-034");for(String file:List.of("players/motionrp_broly_attacker.bbmodel","players/motionrp_broly_victim.bbmodel","models/motionrp_broly_wall.bbmodel","models/motionrp_broly_crater.bbmodel")){byte[] old,now;try(var in=new java.util.zip.GZIPInputStream(getClass().getResourceAsStream("/bundled-0.33.0/"+file.replace('/','_')+".gz"))){old=in.readAllBytes();}try(var in=getClass().getResourceAsStream("/bettermodel/"+file)){now=in.readAllBytes();}var target=root.resolve(file);java.nio.file.Files.createDirectories(target.getParent());java.nio.file.Files.write(target,old);var u=new BundledAssetUpdater();var hashes=BundledAssetVersions.knownHashes(file,Set.of());assertEquals(BundledAssetUpdater.Result.UPDATED,u.install(target,now,hashes,root.resolve("backups"),root.resolve("updates")));assertTrue(java.nio.file.Files.exists(root.resolve("backups").resolve(target.getFileName()+"."+BundledAssetUpdater.sha256(old)+".bak")));java.nio.file.Files.writeString(target,"custom");assertEquals(BundledAssetUpdater.Result.CUSTOM_PRESERVED,u.install(target,now,hashes,root.resolve("backups"),root.resolve("updates")));}
 }

}
